function normalizedMode(mode){
const m = String(mode || '').toLowerCase().replace(/[^a-z]/g,'');
if(m === 'coop') return 'coop';
if(m === 'general') return 'general';
return m;
}
function normalizedPaymentType(value){
const v = String(value || '').trim().toLowerCase().replace(/[^a-z]/g,'');
if(v === 'spot') return 'spot';
if(v === 'mis') return 'mis';
return v;
}
function cloneFilters(filters=activeFilters){
return {mode:new Set(filters.mode), payment:new Set(filters.payment)};
}
function recordMatchesFilters(rec, filters=activeFilters){
const mode = normalizedMode(rec.mode);
const payment = normalizedPaymentType(rec.paymentType);
const modeMatch = filters.mode.size === 0 || filters.mode.has(mode);
const paymentMatch = filters.payment.size === 0 || filters.payment.has(payment);
return modeMatch && paymentMatch;
}
function recordsForActiveFilters(d, filters=activeFilters){
return (d.records || []).filter(rec => recordMatchesFilters(rec, filters));
}
function institutionMatchesFilters(d, filters=activeFilters){
return recordsForActiveFilters(d, filters).length > 0;
}
function bankSearchText(d, filters=activeFilters){
const records = recordsForActiveFilters(d, filters);
return [
d.name,
...unique(records.map(r=>r.bankType)),
...unique(records.map(r=>r.mode)),
...unique(records.map(r=>r.productType)),
...records.flatMap(r => [
r.mode,r.code,r.basis,r.productType,r.variant,r.cities,r.bankType,
r.paymentType,r.documentCategory,r.misDates,r.invoicingProcess,
r.slab,r.topSlabLoanVal,r.highestPayoutPct,r.additionalPayoutPct,
r.payoutCapping,r.institutionType
])
].filter(Boolean).join(' ').toLowerCase();
}
function getFiltered(filters=activeFilters){
const q = comboInput.value.trim().toLowerCase();
return CATALOG_DATA.filter(d => {
if(!institutionMatchesFilters(d,filters)) return false;
const chipMatch = selectedChips.length === 0 || selectedChips.includes(d.name);
const qMatch = !q || bankSearchText(d,filters).includes(q);
return chipMatch && qMatch;
});
}
function countFacet(group,value){
const filters = cloneFilters();
filters[group] = new Set([value]);
return getFiltered(filters).length;
}
