function filterSummaryLabel(){
const parts=[];
if(activeFilters.mode.size){
const labels=[...activeFilters.mode].map(v=>v==='general'?'General':v==='coop'?'Co-Op':v);
parts.push(labels.join(' + '));
}
if(activeFilters.payment.size){
const labels=[...activeFilters.payment].map(v=>v==='spot'?'Spot':v==='mis'?'MIS Based':v);
parts.push(labels.join(' + '));
}
return parts.length ? parts.join(' · ') : 'All Institutions';
}
function extractPercentNumbers(text){
return [...String(text || '').matchAll(/(\d+(?:\.\d+)?)%/g)].map(m=>parseFloat(m[1])).filter(Number.isFinite);
}
function institutionPayoutSortValue(d){
if(!canShowPayouts()) return null;
const nums=recordsForActiveFilters(d).flatMap(rec=>extractPercentNumbers(payoutForRecord(rec)));
return nums.length ? Math.max(...nums) : null;
}
function sortInstitutions(list){
const out=[...list];
if(sortMode==='name-desc') return out.sort((a,b)=>b.name.localeCompare(a.name,'en',{sensitivity:'base'}));
if(sortMode==='payout-high' || sortMode==='payout-low'){
const dir=sortMode==='payout-high' ? -1 : 1;
return out.sort((a,b)=>{
const av=institutionPayoutSortValue(a), bv=institutionPayoutSortValue(b);
if(av===null && bv===null) return a.name.localeCompare(b.name,'en',{sensitivity:'base'});
if(av===null) return 1;
if(bv===null) return -1;
if(av!==bv) return (av-bv)*dir;
return a.name.localeCompare(b.name,'en',{sensitivity:'base'});
});
}
return out.sort((a,b)=>a.name.localeCompare(b.name,'en',{sensitivity:'base'}));
}
