// Progressive bank-card rendering:
// - Desktop grid: 3 visual rows per batch.
// - Desktop list: 3 list rows per batch.
// - Mobile: 5 institutions per batch.
// The next batch is rendered only when the user reaches the end of the
// bank-results scroller, keeping the initial DOM substantially smaller.
let progressiveRenderSignature = '';
let progressiveVisibleCount = 0;
let progressiveFilteredCache = [];
let progressiveLoading = false;
let progressiveLoadTimer = null;
function progressiveBatchSize(){
if(window.matchMedia('(max-width:760px)').matches) return 5;
if(catalogLayout === 'list') return 3;
const grid = document.getElementById('grid');
if(!grid) return 18;
// Ask the browser how many responsive grid tracks currently exist.
// This makes "3 rows" adapt automatically to the actual desktop width.
const template = getComputedStyle(grid).gridTemplateColumns;
let columns = 0;
if(template && template !== 'none') columns = template.trim().split(/\s+/).filter(Boolean).length;
// Fallback for browsers that do not resolve auto-fill tracks on an empty grid.
if(!columns){
const styles = getComputedStyle(grid);
const gap = parseFloat(styles.columnGap || styles.gap) || 9;
const minCardWidth = 185;
columns = Math.max(1, Math.floor((grid.clientWidth + gap) / (minCardWidth + gap)));
}
return Math.max(1, columns) * 3;
}
function progressiveStateSignature(filtered, grid){
const userId = selectedUser && selectedUser.id ? selectedUser.id : '';
const modes = [...activeFilters.mode].sort().join(',');
const payments = [...activeFilters.payment].sort().join(',');
return [
catalogLayout,currentView,userId,sortMode,modes,payments,
comboInput.value.trim().toLowerCase(),selectedChips.join('|'),
Math.round((grid && grid.clientWidth) || 0),
filtered.map(d=>d.name).join('|')
].join('::');
}
