function buildPrintSource(list){
return `<div id="print-source" aria-hidden="true">${list.map((d,bankIndex)=>{
const records=recordsForActiveFilters(d);
if(!records.length) return '';
return `<section class="bank bank-source" data-bank-index="${bankIndex}"><h2>${esc(d.name)}</h2>${records.map(printRecord).join('')}</section>`;
}).join('')}</div>`;
}
function buildPrintBody(list){
const printedOn = new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});
return `<div id="print-pages"><section class="print-sheet cover-sheet">${buildPrintCoverContent()}${buildPrintFooter(printedOn)}</section></div>${buildPrintSource(list)}`;
}
const ADMIN_FIELDS = [
['institution','Institution'],['mode','General / Co-Op'],['productType','Product'],['variant','Variant'],['code','Code'],['basis','Payout Basis'],['payoutRaw','Payout % / Source'],['highestPayoutPct','Max Slab %'],['additionalPayoutPct','Additional Payout %'],['slab','Slab'],['topSlabLoanVal','Top Slab Loan Value'],['payoutCapping','Payout Capping'],['conditions','Conditions'],['timeline','Timeline'],['cities','City / Applicability'],['paymentType','Payment Type'],['bankType','Bank Type'],['institutionType','Institution Type'],['documentCategory','Document Category'],['misDates','MIS Dates'],['invoicingProcess','Invoicing Process'],['loginProcess','Login Process']
];
let adminAuditTrail = [];
function loadAdminAudit(){
try{ const a=JSON.parse(localStorage.getItem(INTERNAL_AUDIT_STORAGE_KEY)||'[]'); adminAuditTrail=Array.isArray(a)?a:[]; }catch(e){adminAuditTrail=[];}
}
function saveAdminAudit(){ try{ localStorage.setItem(INTERNAL_AUDIT_STORAGE_KEY,JSON.stringify(adminAuditTrail.slice(0,1000))); }catch(e){} }
function persistAdminDataset(){
try{ localStorage.setItem(INTERNAL_DATA_STORAGE_KEY,JSON.stringify(CATALOG_DATA)); return true; }
catch(e){ console.error('Could not save Internal dataset',e); alert('The browser could not save this edit locally. Download the updated JSON and replace the server file.'); return false; }
}
function applyStoredAdminDataset(payload){
try{ const saved=JSON.parse(localStorage.getItem(INTERNAL_DATA_STORAGE_KEY)||'null'); if(Array.isArray(saved) && saved.length) return saved; }
catch(e){ console.warn('Stored Internal dataset ignored',e); }
return payload;
}
function recomputeInstitutionMeta(inst){
inst.bankTypes=unique((inst.records||[]).map(r=>r.bankType));
inst.modes=unique((inst.records||[]).map(r=>r.mode));
inst.productTypes=unique((inst.records||[]).map(r=>r.productType));
}
function auditAdminChange(entry){
adminAuditTrail.unshift({changedAt:new Date().toISOString(),user:authenticatedUser?.label||'Internal Team',...entry});
if(adminAuditTrail.length>1000) adminAuditTrail.length=1000;
saveAdminAudit(); renderAdminAudit();
}
function adminFlatRows(){ const out=[]; CATALOG_DATA.forEach((inst,bankIndex)=>(inst.records||[]).forEach((rec,recordIndex)=>out.push({inst,rec,bankIndex,recordIndex}))); return out; }
function adminCellValue(row,field){ return field==='institution' ? row.inst.name : (row.rec[field]??''); }
function adminSearchRows(rows){
const q=String(document.getElementById('data-admin-search')?.value||'').trim().toLowerCase();
if(!q) return rows;
return rows.filter(row=>ADMIN_FIELDS.some(([f])=>String(adminCellValue(row,f)||'').toLowerCase().includes(q)));
}
function renderAdminTable(){
if(!isInternalAuthenticated()) return;
const thead=document.getElementById('data-admin-thead'),tbody=document.getElementById('data-admin-tbody'); if(!thead||!tbody) return;
const rows=adminSearchRows(adminFlatRows());
thead.innerHTML='<tr>'+ADMIN_FIELDS.map(([field,label])=>`<th>${esc(label)}</th>`).join('')+'<th>Action</th></tr>';
tbody.innerHTML=rows.map(row=>{
const cells=ADMIN_FIELDS.map(([field])=>{
const cls=['data-admin-cell']; if(field==='institution') cls.push('admin-col-institution'); if(['conditions','slab','timeline','variant'].includes(field)) cls.push('admin-col-'+field);
return `<td><div class="${cls.join(' ')}" contenteditable="true" spellcheck="false" data-bank-index="${row.bankIndex}" data-record-index="${row.recordIndex}" data-field="${esc(field)}">${esc(adminCellValue(row,field))}</div></td>`;
}).join('');
return `<tr data-bank-index="${row.bankIndex}" data-record-index="${row.recordIndex}">${cells}<td class="data-admin-row-actions"><button type="button" class="data-admin-delete" data-bank-index="${row.bankIndex}" data-record-index="${row.recordIndex}">Delete</button></td></tr>`;
}).join('');
const total=CATALOG_DATA.reduce((n,d)=>n+(d.records||[]).length,0);
const statusEl=document.getElementById('data-admin-status'); if(statusEl) statusEl.textContent=`Showing ${rows.length} of ${total} product records across ${CATALOG_DATA.length} institutions · edits auto-save in this browser`;
tbody.querySelectorAll('.data-admin-cell').forEach(cell=>{
cell.addEventListener('focus',()=>{ cell.dataset.before=cell.innerText; });
cell.addEventListener('blur',()=>commitAdminCell(cell));
cell.addEventListener('keydown',e=>{ if(e.key==='Enter' && !e.shiftKey && !['conditions','slab','timeline','variant','loginProcess','invoicingProcess'].includes(cell.dataset.field)){ e.preventDefault(); cell.blur(); } });
});
tbody.querySelectorAll('.data-admin-delete').forEach(btn=>btn.addEventListener('click',()=>deleteAdminRow(Number(btn.dataset.bankIndex),Number(btn.dataset.recordIndex))));
}
function commitAdminCell(cell){
if(!isInternalAuthenticated()) return;
const bankIndex=Number(cell.dataset.bankIndex),recordIndex=Number(cell.dataset.recordIndex),field=cell.dataset.field;
const inst=CATALOG_DATA[bankIndex],rec=inst?.records?.[recordIndex]; if(!inst||!rec) return;
const before=String(cell.dataset.before??adminCellValue({inst,rec},field)); const after=cell.innerText.replace(/\r/g,'').trim(); if(before===after) return;
const oldProduct=rec.productType||''; if(field==='institution') inst.name=after; else rec[field]=after;
recomputeInstitutionMeta(inst); persistAdminDataset();
auditAdminChange({institution:inst.name,product:rec.productType||oldProduct,field:ADMIN_FIELDS.find(x=>x[0]===field)?.[1]||field,oldValue:before,newValue:after});
progressiveRenderSignature=''; renderGrid();
}
function blankAdminRecord(){ return {mode:'General',code:'',basis:'',productType:'HL',variant:'',payoutRaw:'',timeline:'',cities:'PAN India',conditions:'',loginProcess:'',bankType:'',paymentType:'',documentCategory:'',misDates:'',invoicingProcess:'',slab:'',topSlabLoanVal:'',highestPayoutPct:'',additionalPayoutPct:'',payoutCapping:'',institutionType:''}; }
function addAdminRecord(){
if(!isInternalAuthenticated()) return;
const name=prompt('Institution name for the new record:'); if(name===null||!String(name).trim()) return;
const clean=String(name).trim(); let inst=CATALOG_DATA.find(d=>String(d.name).toLowerCase()===clean.toLowerCase()); let createdInstitution=false;
if(!inst){ inst={name:clean,records:[],bankTypes:[],modes:[],productTypes:[]}; CATALOG_DATA.push(inst); createdInstitution=true; }
const rec=blankAdminRecord(); inst.records.push(rec); recomputeInstitutionMeta(inst); persistAdminDataset();
auditAdminChange({institution:inst.name,product:rec.productType,field:createdInstitution?'Institution + Product Record':'Product Record',oldValue:'',newValue:'Added'});
renderAdminTable(); progressiveRenderSignature=''; renderGrid();
}
function deleteAdminRow(bankIndex,recordIndex){
if(!isInternalAuthenticated()) return;
const inst=CATALOG_DATA[bankIndex],rec=inst?.records?.[recordIndex]; if(!inst||!rec) return;
if(!confirm(`Delete ${inst.name} · ${rec.productType||'record'} · ${rec.code||'no code'}?`)) return;
const snapshot=JSON.stringify(rec); inst.records.splice(recordIndex,1); if(!inst.records.length) CATALOG_DATA.splice(bankIndex,1); else recomputeInstitutionMeta(inst);
persistAdminDataset(); auditAdminChange({institution:inst.name,product:rec.productType||'',field:'Product Record',oldValue:snapshot,newValue:'Deleted'});
renderAdminTable(); progressiveRenderSignature=''; renderGrid();
}
function renderAdminAudit(){
const body=document.getElementById('data-admin-audit-body'),count=document.getElementById('data-admin-audit-count'); if(!body||!count) return;
count.textContent=`${adminAuditTrail.length} change${adminAuditTrail.length===1?'':'s'} retained`;
body.innerHTML=adminAuditTrail.slice(0,250).map(a=>`<tr><td>${esc(new Date(a.changedAt).toLocaleString('en-IN'))}</td><td>${esc(a.user)}</td><td>${esc(a.institution)}</td><td>${esc(a.product)}</td><td>${esc(a.field)}</td><td>${esc(a.oldValue)}</td><td>${esc(a.newValue)}</td></tr>`).join('') || '<tr><td colspan="7">No changes recorded yet.</td></tr>';
}
