// Load the next card batch only after the user reaches the bottom of the
// bank-results scroller. Wheel support also covers a desktop viewport where
// the first 3 rows happen to fit without creating a visible scrollbar.
const progressiveBankScroll = document.getElementById('bank-scroll');
if(progressiveBankScroll){
progressiveBankScroll.addEventListener('scroll',()=>{
if(progressiveScrollerAtEnd(progressiveBankScroll)) loadNextProgressiveBatch();
},{passive:true});
progressiveBankScroll.addEventListener('wheel',e=>{
if(e.deltaY > 0 && progressiveScrollerAtEnd(progressiveBankScroll)) loadNextProgressiveBatch();
},{passive:true});
}
