function initializeCatalogUI(){
loadAdminAudit();
updateMasterCatalogToolLabel();
status.className='live-status live';
status.innerHTML=`<span class="dot"></span>${esc(SOURCE_LABEL)} · ${CATALOG_DATA.length} institutions · ${CATALOG_DATA.reduce((n,d)=>n+d.records.length,0)} product records`;
const restoredAuth = restoreAuth();
if(restoredAuth){
populateInternalUserViews();
}else{
authenticatedUser = null;
selectedUser = null;
currentView = 'catalog';
applyAuthUI();
}
renderChips();
updateComboState();
renderGrid();
}
async function loadCatalogData(){
try{
const response = await fetch('./catalog-data.json', { cache:'default' });
if(!response.ok) throw new Error(`HTTP ${response.status}`);
const payload = await response.json();
if(!Array.isArray(payload)) throw new Error('Catalog payload is not an array');
CATALOG_DATA = applyStoredAdminDataset(payload);
initializeCatalogUI();
}catch(error){
console.error('Unable to load catalog-data.json:', error);
status.className='live-status error';
status.innerHTML='<span class="dot"></span>Catalog data could not be loaded. Ensure catalog-data.json is deployed beside this HTML file.';
const grid = document.getElementById('grid');
const empty = document.getElementById('empty');
if(grid) grid.innerHTML='';
if(empty){
empty.style.display='block';
empty.textContent='Unable to load the banking catalog. Please refresh the page or contact the administrator.';
}
}
}
loadCatalogData();
(() => {
'use strict';
// Disable the standard right-click context menu.
document.addEventListener('contextmenu', event => {
event.preventDefault();
}, { capture: true });
// Block the most common browser shortcuts used to open DevTools, View Source, or Save Page.
document.addEventListener('keydown', event => {
const key = String(event.key || '').toLowerCase();
const ctrlOrMeta = event.ctrlKey || event.metaKey;
const shift = event.shiftKey;
const alt = event.altKey;
const windowsLinuxDevTools = ctrlOrMeta && shift && ['i', 'j', 'c', 'k'].includes(key);
const macDevTools = event.metaKey && alt && ['i', 'j', 'c', 'u'].includes(key);
const viewSource = ctrlOrMeta && key === 'u';
const savePage = ctrlOrMeta && key === 's';
const f12 = event.key === 'F12' || event.keyCode === 123;
if (f12 || windowsLinuxDevTools || macDevTools || viewSource || savePage) {
event.preventDefault();
event.stopImmediatePropagation();
return false;
}
}, { capture: true });
})();
(function(){
'use strict';
function syncViewport(){
const w = Math.max(document.documentElement.clientWidth || 0, window.innerWidth || 0);
const h = Math.max(document.documentElement.clientHeight || 0, window.innerHeight || 0);
const aw = window.screen && screen.availWidth ? screen.availWidth : w;
const ah = window.screen && screen.availHeight ? screen.availHeight : h;
document.documentElement.style.setProperty('--viewport-w', w + 'px');
document.documentElement.style.setProperty('--viewport-h', h + 'px');
document.documentElement.dataset.viewport = w + 'x' + h;
document.documentElement.dataset.availableScreen = aw + 'x' + ah;
}
syncViewport();
window.addEventListener('resize', syncViewport, {passive:true});
window.addEventListener('orientationchange', syncViewport, {passive:true});
const bankScroll = document.getElementById('bank-scroll');
const catalogBtn = document.getElementById('bottom-nav-catalog');
if(catalogBtn && bankScroll){
catalogBtn.addEventListener('click', function(){ if(document.body.classList.contains('catalog-history-open') && typeof setView === 'function') setView('catalog'); bankScroll.scrollTo({top:0,behavior:'smooth'}); });
}
const directoryOverlay = document.getElementById('call-directory-overlay');
const directoryBtn = document.getElementById('call-directory-btn');
const directoryClose = document.getElementById('call-directory-close');
function openDirectory(){ if(directoryOverlay){ directoryOverlay.classList.add('open'); directoryOverlay.setAttribute('aria-hidden','false'); } }
function closeDirectory(){ if(directoryOverlay){ directoryOverlay.classList.remove('open'); directoryOverlay.setAttribute('aria-hidden','true'); } }
if(directoryBtn) directoryBtn.addEventListener('click', openDirectory);
if(directoryClose) directoryClose.addEventListener('click', closeDirectory);
if(directoryOverlay) directoryOverlay.addEventListener('click', function(e){ if(e.target === directoryOverlay) closeDirectory(); });
const contactWrap = document.getElementById('bottom-nav-contact');
const contactTrigger = document.getElementById('contact-trigger');
if(contactTrigger && contactWrap){
contactTrigger.addEventListener('click', function(e){
e.stopPropagation();
const open = contactWrap.classList.toggle('open');
contactTrigger.setAttribute('aria-expanded', open ? 'true' : 'false');
});
document.addEventListener('click', function(e){
if(!contactWrap.contains(e.target)){
contactWrap.classList.remove('open');
contactTrigger.setAttribute('aria-expanded','false');
}
});
}
const adOverlay = document.getElementById('onboarding-ad-overlay');
const adClose = document.getElementById('onboarding-ad-close');
let adTimer = null;
function showAd(){
if(!adOverlay) return;
adOverlay.classList.add('open');
adOverlay.setAttribute('aria-hidden','false');
}
function closeAd(){
if(!adOverlay) return;
adOverlay.classList.remove('open');
adOverlay.setAttribute('aria-hidden','true');
}
if(adClose) adClose.addEventListener('click', closeAd);
if(adOverlay) adOverlay.addEventListener('click', function(e){ if(e.target === adOverlay) closeAd(); });
// Desktop: 10 seconds. Mobile: 5 seconds.
const mobile = window.matchMedia('(max-width: 760px)').matches;
adTimer = window.setTimeout(showAd, mobile ? 5000 : 10000);
document.addEventListener('keydown', function(e){
if(e.key === 'Escape'){
closeDirectory();
closeAd();
}
});
})();
